(1944, 'margin', '/ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["邊緣；利潤率；差額"],"en":["the edge of something; the amount of profit"]}', NULL, 'profit margin / by a narrow margin / margin of error', '[{"en":"The company''s profit margin increased to 15%.","zh-TW":"公司的利潤率增至15%。"},{"en":"He won the election by a narrow margin.","zh-TW":"他以微弱的差距贏得了選舉。"}]', '{"noun":"margin","adjective":"marginal","adverb":"marginally"}', NULL, 2, 1944, 390),
(1945, 'maritime', '/ˈmærɪtaɪm/', 'adjective', '{"zh-TW":["海事的；海運的"],"en":["relating to the sea or shipping"]}', NULL, 'maritime law/industry/trade', '[{"en":"Maritime trade accounts for 80% of global commerce.","zh-TW":"海運貿易佔全球商業的80%。"},{"en":"Maritime law governs shipping disputes.","zh-TW":"海事法管轄航運糾紛。"}]', '{"noun":"maritime","adjective":"maritime"}', NULL, 3, 1945, NULL),
(1946, 'mark', '/mɑːrk/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】標記；記號","【次要意義-動詞】留意；注意（尤其在命令句中）","【次要意義-名詞】成績；分數","【次要意義-動詞】紀念；標誌著（事件）"],"en":["[primary] to make a visible sign; a visible sign","[secondary - verb] to notice and remember something (especially in imperatives)","[secondary - noun] a score or grade in academic work","[secondary - verb] to commemorate; to indicate an important event"]}', NULL, 'mark my words / mark an occasion / up to the mark / on your mark / benchmark', '[{"en":"Mark my words, this policy will cause serious problems.","zh-TW":"請記住我的話，這項政策將引發嚴重問題。"},{"en":"The ceremony marks the 50th anniversary of the company.","zh-TW":"這個儀式標誌著公司成立50週年。"},{"en":"The new product launch marks a turning point in the company history.","zh-TW":"新產品的發布標誌著公司歷史的轉折點。"}]', '{"noun":"marker, marking, benchmark","adjective":"marked"}', 'mark my words（請記住我的話）、mark an occasion（紀念某場合）、marked improvement（顯著的改善）均為 TOEIC 常見用法，動詞 mark = 「標誌著/紀念」在公司周年文章中常見。', 1, 1946, NULL),
(1947, 'mark-to-market', '/mɑːrk tə ˈmɑːrkɪt/', 'verb', '{"zh-TW":["按市價計算；市值計算"],"en":["to revalue an asset at its current market price rather than its original cost"]}', NULL, 'mark-to-market valuation / mark-to-market accounting', '[{"en":"The portfolio is revalued daily using mark-to-market accounting.","zh-TW":"投資組合使用市值計算每日重新估值。"},{"en":"Mark-to-market accounting increases transparency but adds volatility.","zh-TW":"市值計算會計增加了透明度，但也增加了波動性。"}]', NULL, NULL, 5, 1947, NULL),
(1948, 'market', '/ˈmɑːrkɪt/', 'noun, verb', '{"zh-TW":["市場","推銷；銷售"],"en":["a place where goods are sold; demand for goods","to advertise and sell"]}', NULL, 'market share / target market / market research', '[{"en":"We need to conduct market research before launching.","zh-TW":"我們需要在推出前進行市場調查。"},{"en":"The product was successfully marketed to young professionals.","zh-TW":"該產品成功地向年輕專業人士推銷。"}]', '{"noun":"market, marketing, marketer","verb":"market","adjective":"marketable"}', NULL, 2, 1948, NULL),
(1949, 'markup', '/ˈmɑːrkʌp/', 'noun', '{"zh-TW":["加價；標記"],"en":["the amount added to cost price for profit"]}', NULL, 'price markup / markup percentage', '[{"en":"Retailers typically apply a 50% markup on wholesale prices.","zh-TW":"零售商通常在批發價上加價50%。"},{"en":"The markup on luxury goods is significantly higher.","zh-TW":"奢侈品的加價幅度明顯更高。"}]', '{"noun":"markup","verb":"mark up"}', NULL, 2, 1949, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1950, 'marry', '/ˈmæri/', 'verb', '{"zh-TW":["結婚"],"en":["to become the spouse of someone"]}', NULL, 'get married / married life', '[{"en":"They got married last summer.","zh-TW":"他們去年夏天結婚了。"},{"en":"She is married with two children.","zh-TW":"她已婚並育有兩個孩子。"}]', '{"verb":"marry","noun":"marriage","adjective":"married","adjective2":"unmarried"}', NULL, 2, 1950, NULL),
(1951, 'massive', '/ˈmæsɪv/', 'adjective', '{"zh-TW":["大量的；巨大的"],"en":["extremely large or serious"]}', NULL, 'massive investment/growth/change', '[{"en":"The project requires a massive investment.","zh-TW":"該項目需要大量投資。"},{"en":"There has been massive growth in online shopping.","zh-TW":"網上購物出現了大幅增長。"}]', '{"noun":"mass","adjective":"massive","adverb":"massively"}', NULL, 3, 1951, NULL),
(1952, 'master', '/ˈmæstər/', 'noun, verb, adjective', '{"zh-TW":["【主要意義-名詞】主人；碩士","【次要意義-動詞】精通；掌握（技能）","【次要意義-形容詞】主要的；最終版本的（文件）","【次要意義-名詞】原版；母片"],"en":["[primary - noun] a person with great skill or authority","[secondary - verb] to become skilled at something through practice","[secondary - adjective] relating to the main or original version of something","[secondary - noun] an original recording or document"]}', NULL, 'master plan / master copy / master a skill / master key', '[{"en":"It takes years of practice to master the art of negotiation.","zh-TW":"掌握談判藝術需要多年的練習。"},{"en":"Please send the master copy of the contract to the legal department.","zh-TW":"請將合約的原版副本發送至法律部門。"},{"en":"The company revealed its master plan for expansion into Southeast Asia.","zh-TW":"公司公布了其向東南亞擴張的總體計劃。"}]', '{"noun":"masterpiece, mastery","adjective":"masterful"}', '動詞 master = 「精通/掌握」是高頻用法；master plan（總體計劃）、master copy（原版）、master key（萬能鑰匙）均是 TOEIC 商業和管理文章常見搭配。', 2, 1952, NULL),
(1953, 'masterpiece', '/ˈmæstərpiːs/', 'noun', '{"zh-TW":["傑作"],"en":["a work of outstanding artistry or skill"]}', '{"root":{"text":"master","meaning":"master (大師)"},"suffix":{"text":"piece","meaning":"piece/work (作品)"},"logic":"大師的作品，即「傑作」。"}', 'literary masterpiece / create a masterpiece', '[{"en":"The Mona Lisa is considered a masterpiece.","zh-TW":"蒙娜麗莎被視為傑作。"},{"en":"This novel is his greatest masterpiece.","zh-TW":"這部小說是他最偉大的傑作。"}]', NULL, NULL, 4, 1953, NULL),
(1954, 'match', '/mætʃ/', 'verb', '{"zh-TW":["匹配；比賽"],"en":["to be equal to","a contest"]}', NULL, 'perfect match / match up', '[{"en":"We need a candidate who matches the job requirements.","zh-TW":"我們需要一位符合工作要求的候選人。"},{"en":"Her skills are a perfect match for the role.","zh-TW":"她的技能與這個職位完美匹配。"}]', '{"verb":"match","noun":"match","adjective":"matching"}', NULL, 2, 1954, NULL),
(1955, 'material', '/məˈtɪriəl/', 'noun, adjective', '{"zh-TW":["材料；物質","重要的；物質的"],"en":["the substance things are made from","significant; relating to physical things"]}', NULL, 'raw material / reading material / material change', '[{"en":"The cost of raw materials has risen sharply.","zh-TW":"原材料成本大幅上升。"},{"en":"There has been no material change in our financial position.","zh-TW":"我們的財務狀況沒有重大變化。"}]', '{"noun":"material, materialism","adjective":"material","adverb":"materially"}', NULL, 3, 1955, 391),
(1956, 'materiality', '/məˌtɪəriˈæləti/', 'noun', '{"zh-TW":["重大性；重要性"],"en":["the significance of information in relation to financial decisions"]}', NULL, 'assess materiality / materiality threshold', '[{"en":"The auditor determined the materiality threshold at 1% of revenue.","zh-TW":"審計師將重大性門檻確定為收入的1%。"},{"en":"Materiality determines what information must be disclosed in accounts.","zh-TW":"重大性決定了帳目中必須披露的資訊。"}]', '{"adjective":"material","adverb":"materially"}', NULL, 4, 1956, NULL),
(1957, 'matrix', '/ˈmeɪtrɪks/', 'noun', '{"zh-TW":["矩陣；基質"],"en":["a grid arrangement; an environment in which something develops"]}', NULL, 'decision matrix / risk matrix / matrix organization', '[{"en":"We used a decision matrix to evaluate options.","zh-TW":"我們使用決策矩陣來評估選項。"},{"en":"The company operates under a matrix structure.","zh-TW":"公司以矩陣結構運作。"}]', '{"noun":"matrix"}', NULL, 2, 1957, NULL),
(1958, 'matter', '/ˈmætər/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】事情；物質；問題","【次要意義-動詞】重要；有關係；有影響"],"en":["[primary - noun] a subject or situation; physical substance","[secondary - verb] to be important or significant"]}', NULL, 'it matters / matter of fact / no matter what / as a matter of course', '[{"en":"It matters a great deal how we communicate with our clients.","zh-TW":"我們與客戶的溝通方式非常重要。"},{"en":"As a matter of policy, all complaints must be addressed within 48 hours.","zh-TW":"按照慣例，所有投訴必須在48小時內處理。"},{"en":"The timing of the announcement matters more than its content.","zh-TW":"公告的時機比其內容更為重要。"}]', '{"adjective":"immaterial"}', '動詞 matter = 「重要/有意義」，常見句型 it matters that.../ what matters is...，片語 as a matter of + noun（作為……事項）是 TOEIC 商業文章常見正式表達。', 2, 1958, NULL),
(1959, 'mature', '/məˈtʃʊr/', 'adjective, verb', '{"zh-TW":["成熟的","到期；成熟"],"en":["fully developed; sensible","to reach full development; (of investments) to reach payment date"]}', NULL, 'mature market/industry / bond matures', '[{"en":"The market has matured and growth is slowing.","zh-TW":"市場已經成熟，增長正在放緩。"},{"en":"The bond matures in five years.","zh-TW":"債券五年後到期。"}]', '{"noun":"maturity","adjective":"mature","verb":"mature"}', NULL, 2, 1959, NULL),
(1960, 'maximize', '/ˈmæksɪmaɪz/', 'verb', '{"zh-TW":["最大化；充分利用"],"en":["to make as large or great as possible"]}', NULL, 'maximize profit/efficiency/potential', '[{"en":"We aim to maximize shareholder value.","zh-TW":"我們的目標是最大化股東價值。"},{"en":"How can we maximize the use of our resources?","zh-TW":"我們如何才能最大限度地利用資源？"}]', '{"noun":"maximum","verb":"maximize","adjective":"maximum"}', NULL, 3, 1960, 153),
(1961, 'maximum', 'ˈmæksɪməm', 'noun', '{"zh-TW":["最大值；最大量","極限"],"en":["the greatest possible amount","an upper limit"]}', NULL, 'maximum capacity/at maximum', '[{"en":"We are at maximum production capacity.","zh-TW":"我們處於最大生產能力。"}]', '{"adjective":"maximum","adverb":"maximally"}', NULL, 3, 1961, 392),
(1962, 'meal', '/miːl/', 'noun', '{"zh-TW":["一餐；膳食"],"en":["food eaten at a particular time"]}', NULL, 'meal allowance / business meal', '[{"en":"Employees receive a meal allowance.","zh-TW":"員工有餐費補貼。"},{"en":"Business meals are tax-deductible.","zh-TW":"商務餐費可以扣稅。"}]', '{"noun":"meal"}', NULL, 1, 1962, NULL),
(1963, 'mean', '/miːn/', 'verb', '{"zh-TW":["【主要意義-動詞】意味著；表示","【次要意義-形容詞】低賤的；吝嗇的；惡劣的；殘忍的","【次要意義-名詞（數學）】平均數；中間值","【次要意義-形容詞】出色的；高超的（非正式）"],"en":["[primary - verb] to signify or indicate something","[secondary - adjective] unkind or cruel; unwilling to give","[secondary - noun] a middle point or average value","[secondary - adjective] (informal) excellent or skillful"]}', NULL, 'mean business / by no means / means of communication / golden mean', '[{"en":"The new director means business and has already implemented major changes.","zh-TW":"新主任是認真的，已經實施了重大改革。"},{"en":"This is by no means a simple task and requires expert guidance.","zh-TW":"這絕非一項簡單的任務，需要專家指導。"},{"en":"The mean salary in the sector increased by 5 percent last year.","zh-TW":"該行業的平均薪資去年增加了5%。"}]', '{"noun":"meaning, means","adjective":"meaningful"}', 'mean business（認真對待）、by no means（絕不）、means（方法/手段）是 TOEIC 高頻表達；形容詞 mean = 「吝嗇的/惡劣的」，名詞 mean = 「平均值」均是次要意義陷阱。', 1, 1963, NULL),
(1964, 'meaning', 'ˈmiːnɪŋ', 'noun', '{"zh-TW":["意義；含義","目的"],"en":["what something represents","the importance of something"]}', NULL, 'hidden meaning/double meaning', '[{"en":"What is the meaning of this abbreviation?","zh-TW":"這個縮寫的含義是什麼？"}]', '{"verb":"mean","adjective":"meaningful, meaningless","adverb":"meaningfully"}', NULL, 3, 1964, NULL),
(1965, 'measurable', 'ˈmɛʒərəbəl', 'adjective', '{"zh-TW":["可衡量的；可測量的","有具體結果的"],"en":["able to be measured","quantifiable"]}', NULL, 'measurable results/measurable goals', '[{"en":"Set measurable goals for each quarter.","zh-TW":"為每個季度設定可衡量的目標。"}]', '{"verb":"measure","noun":"measurement","adverb":"measurably"}', NULL, 4, 1965, NULL),
(1966, 'measure', '/ˈmeʒər/', 'noun, verb', '{"zh-TW":["措施；測量","測量；衡量"],"en":["an action taken to achieve a purpose; size or amount","to find the size or amount of something"]}', NULL, 'take measures / safety measures / measure performance', '[{"en":"The government took measures to reduce pollution.","zh-TW":"政府採取了減少污染的措施。"},{"en":"We need to measure the effectiveness of the campaign.","zh-TW":"我們需要衡量這次活動的效果。"}]', '{"noun":"measure, measurement","verb":"measure","adjective":"measurable"}', NULL, 3, 1966, 154),
(1967, 'mechanism', '/ˈmekənɪzəm/', 'noun', '{"zh-TW":["機制；機構"],"en":["a system of parts working together; a process"]}', NULL, 'feedback mechanism / pricing mechanism / defense mechanism', '[{"en":"We need a mechanism for handling complaints.","zh-TW":"我們需要一套處理投訴的機制。"},{"en":"The pricing mechanism is determined by supply and demand.","zh-TW":"定價機制由供需決定。"}]', '{"noun":"mechanism","adjective":"mechanical","verb":"mechanize"}', NULL, 3, 1967, NULL),
(1968, 'medal', '/ˈmɛdəl/', 'noun', '{"zh-TW":["獎牌"],"en":["a flat piece of metal given as a prize"]}', NULL, 'gold medal / win a medal', '[{"en":"She won a gold medal at the Olympics.","zh-TW":"她在奧運會上贏得了金牌。"},{"en":"The team brought home three medals.","zh-TW":"隊伍帶回了三面獎牌。"}]', '{"noun2":"medalist"}', NULL, 2, 1968, NULL),
(1969, 'media', '/ˈmiːdiə/', 'noun', '{"zh-TW":["媒體"],"en":["the main means of mass communication"]}', NULL, 'social media / media coverage / media outlet', '[{"en":"Social media has transformed how companies market products.","zh-TW":"社群媒體改變了公司行銷產品的方式。"},{"en":"The event received extensive media coverage.","zh-TW":"這個活動獲得了廣泛的媒體報導。"}]', '{"noun":"media, medium","adjective":"medial"}', NULL, 2, 1969, 393),
(1970, 'mediate', '/ˈmiːdieɪt/', 'verb', '{"zh-TW":["調解；斡旋"],"en":["to try to end a disagreement between parties"]}', NULL, 'mediate a dispute / mediate between', '[{"en":"A neutral party was brought in to mediate the dispute.","zh-TW":"引入了中立方來調解爭端。"},{"en":"She mediated between management and the union.","zh-TW":"她在管理層和工會之間進行調解。"}]', '{"noun":"mediation, mediator","verb":"mediate"}', NULL, 3, 1970, NULL),
(1971, 'mediation', '/ˌmiːdiˈeɪʃən/', 'noun', '{"zh-TW":["調解；斡旋"],"en":["a process where a neutral party helps resolve a dispute"]}', NULL, 'go to mediation / mediation process / employment mediation', '[{"en":"Mediation resolved the contract dispute without litigation.","zh-TW":"調解解決了合同糾紛，無需訴訟。"},{"en":"Both parties agreed to enter mediation to settle their differences.","zh-TW":"雙方同意進行調解以解決分歧。"}]', '{"verb":"mediate","noun":"mediator"}', NULL, 3, 1971, NULL),
(1972, 'mediator', '/ˈmiːdieɪtər/', 'noun', '{"zh-TW":["調解人；仲裁者"],"en":["a neutral party who helps resolve a dispute between two or more parties"]}', NULL, 'appoint a mediator / role of the mediator', '[{"en":"Both companies agreed to use a mediator to settle the contract dispute.","zh-TW":"兩家公司同意使用調解人解決合約糾紛。"},{"en":"A skilled mediator can prevent costly litigation.","zh-TW":"熟練的調解人可以防止代價高昂的訴訟。"}]', '{"verb":"mediate","noun2":"mediation"}', NULL, 3, 1972, NULL),
(1973, 'medication', '/ˌmɛdɪˈkeɪʃən/', 'noun', '{"zh-TW":["藥物；藥品"],"en":["a drug or medicine taken to treat illness"]}', NULL, 'take medication / prescription medication', '[{"en":"She takes daily medication to control her blood pressure.","zh-TW":"她每天服藥來控制血壓。"},{"en":"Never stop taking medication without consulting your doctor.","zh-TW":"不要在未諮詢醫生的情況下停藥。"}]', '{"verb":"medicate","adjective":"medicated"}', NULL, 4, 1973, NULL),
(1974, 'mediocre', '/ˌmiːdiˈoʊkər/', 'adjective', '{"zh-TW":["平庸的；普通的"],"en":["of only average quality; not very good"]}', NULL, 'mediocre performance/results/quality', '[{"en":"Mediocre performance will not be tolerated.","zh-TW":"平庸的表現將不被容忍。"},{"en":"The product received mediocre reviews.","zh-TW":"該產品獲得了普通的評價。"}]', '{"noun":"mediocrity","adjective":"mediocre"}', NULL, 3, 1974, NULL),
(1975, 'medium', '/ˈmiːdiəm/', 'noun, adjective', '{"zh-TW":["媒介；媒體","中等的"],"en":["a means of communication; a middle state","average in size or amount"]}', NULL, 'through the medium of / medium-sized / medium-term', '[{"en":"Email is an effective medium for business communication.","zh-TW":"電子郵件是商務溝通的有效媒介。"},{"en":"The company targets medium-sized businesses.","zh-TW":"該公司以中型企業為目標客戶。"}]', '{"noun":"medium, media","adjective":"medium"}', NULL, 2, 1975, NULL),
(1976, 'meet', '/miːt/', 'verb', '{"zh-TW":["見面；符合"],"en":["to come together with","to satisfy a requirement"]}', NULL, 'meet the deadline / meet expectations', '[{"en":"Can we meet tomorrow at 2?","zh-TW":"我們明天2點見面好嗎？"},{"en":"The product meets all safety standards.","zh-TW":"產品符合所有安全標準。"}]', '{"verb":"meet","noun":"meeting"}', NULL, 1, 1976, NULL),
(1977, 'meeting', 'ˈmiːtɪŋ', 'noun', '{"zh-TW":["會議；開會","集會"],"en":["a gathering to discuss something","an arranged encounter"]}', NULL, 'board meeting/team meeting', '[{"en":"The weekly meeting is on Monday morning.","zh-TW":"每週會議在週一上午舉行。"}]', '{"verb":"meet","adjective":"meeting-related"}', NULL, 3, 1977, 155),
(1978, 'membership', '/ˈmembərʃɪp/', 'noun', '{"zh-TW":["會員資格；會員人數"],"en":["the state of being a member; the total number of members"]}', NULL, 'membership fee / apply for membership', '[{"en":"Membership is open to all employees.","zh-TW":"所有員工都可以申請會員資格。"},{"en":"The club''s membership has grown to 500.","zh-TW":"俱樂部的會員人數已增至500人。"}]', '{"noun":"membership, member"}', NULL, 4, 1978, NULL),
(1979, 'memo', '/ˈmemoʊ/', 'noun', '{"zh-TW":["備忘錄"],"en":["a short written message used in business"]}', NULL, 'send/write a memo / internal memo', '[{"en":"The manager sent a memo to all staff.","zh-TW":"經理向全體員工發送了一份備忘錄。"},{"en":"Please refer to the attached memo for details.","zh-TW":"詳情請參閱附件備忘錄。"}]', '{"noun":"memo, memorandum"}', NULL, 1, 1979, NULL),
(1980, 'memorandum', '/ˌmɛməˈrændəm/', 'noun', '{"zh-TW":["備忘錄"],"en":["a written message in an office or organization"]}', NULL, 'send a memorandum / internal memorandum', '[{"en":"A memorandum was circulated to all staff regarding the policy change.","zh-TW":"一份備忘錄已發送給所有員工，說明政策變更。"},{"en":"The memorandum outlined the new expense reimbursement procedure.","zh-TW":"備忘錄概述了新的費用報銷程序。"}]', '{"plural":"memoranda","abbreviation":"memo"}', NULL, 4, 1980, NULL),
(1981, 'mention', 'ˈmɛnʃən', 'verb', '{"zh-TW":["提及；提到","說到"],"en":["to refer to briefly","to bring up"]}', NULL, 'mention a concern/mention details', '[{"en":"Please mention any special requirements.","zh-TW":"請提及任何特殊要求。"}]', '{"noun":"mention","adjective":"mentioned"}', NULL, 3, 1981, 156),
(1982, 'mentor', '/ˈmɛntɔːr/', 'noun', '{"zh-TW":["導師；良師益友","導師；顧問","指導"],"en":["an experienced person who advises","to guide and advise"]}', NULL, 'find a mentor / mentor program; mentor program / find a mentor / mentor someone', '[{"en":"She became my mentor at work.","zh-TW":"她成為了我工作中的導師。"},{"en":"Every student is assigned a mentor.","zh-TW":"每位學生都被分配了一位導師。"},{"en":"Every new employee is assigned a mentor.","zh-TW":"每位新員工都會被分配一位導師。"},{"en":"She mentored several junior colleagues.","zh-TW":"她指導了幾位初級同事。"}]', '{"verb":"mentor","noun2":"mentorship","noun":"mentor, mentorship, mentoring"}', NULL, 2, 1982, NULL),
(1983, 'mentoring', '/ˈmentərɪŋ/', 'noun', '{"zh-TW":["導師制；輔導"],"en":["a relationship where an experienced person guides a less experienced one"]}', NULL, 'mentoring program / provide mentoring / peer mentoring', '[{"en":"The mentoring program paired junior employees with senior leaders.","zh-TW":"導師計劃將初級員工與資深領導人配對。"},{"en":"She credited her success to strong mentoring early in her career.","zh-TW":"她將成功歸功於職業生涯早期的良好輔導。"}]', '{"verb":"mentor","noun":"mentor"}', NULL, 3, 1983, NULL),
(1984, 'mentorship', '/ˈmentərʃɪp/', 'noun', '{"zh-TW":["指導；師徒關係"],"en":["a relationship where an experienced person guides a junior one"]}', NULL, 'mentorship program / provide mentorship / mentorship relationship', '[{"en":"The mentorship program pairs new staff with senior employees.","zh-TW":"師徒計劃將新員工與資深員工配對。"},{"en":"She credits her success to strong mentorship early in her career.","zh-TW":"她將成功歸功於職業生涯早期良好的指導。"}]', '{"noun":"mentor","verb":"mentor"}', NULL, 4, 1984, NULL),
(1985, 'menu', '/ˈmɛnjuː/', 'noun', '{"zh-TW":["菜單"],"en":["a list of dishes available in a restaurant"]}', NULL, 'browse the menu / set menu', '[{"en":"Please take a moment to look over our menu.","zh-TW":"請花一點時間瀏覽我們的菜單。"},{"en":"The seasonal menu changes every month.","zh-TW":"季節性菜單每月更換。"}]', NULL, NULL, 1, 1985, NULL),
(1986, 'merchandise', '/ˈmɜːrtʃəndaɪz/', 'noun', '{"zh-TW":["商品；貨物","推銷"],"en":["goods that are bought and sold","goods for sale","to promote the sale of goods"]}', '{"root":{"text":"merch","meaning":"trade (貿易)"},"suffix":{"text":"-andise","meaning":"collective (集合)"},"logic":"貿易的集合，即「商品」。"}', 'merchandise display / branded merchandise', '[{"en":"The store sells a wide range of merchandise.","zh-TW":"這家店販售各種商品。"},{"en":"All merchandise must be paid for before leaving.","zh-TW":"所有商品在離開前必須付款。"},{"en":"The store offers a wide range of merchandise.","zh-TW":"這家商店提供各種各樣的商品。"},{"en":"The products were merchandised effectively.","zh-TW":"產品被有效地推銷。"}]', '{"noun":"merchant","verb":"merchandise"}', NULL, 4, 1986, 394),
(1987, 'merchandising', '/ˈmɜːrtʃəndaɪzɪŋ/', 'noun', '{"zh-TW":["商品展示；銷售陳列"],"en":["the promotion of goods for sale in a store"]}', NULL, 'visual merchandising / merchandising strategy', '[{"en":"Good merchandising draws attention to high-margin products.","zh-TW":"良好的商品陳列吸引了對高利潤產品的注意。"},{"en":"The merchandising team redesigned the store layout.","zh-TW":"商品展示團隊重新設計了商店佈局。"}]', '{"verb":"merchandise","noun":"merchandiser"}', NULL, 5, 1987, NULL),
(1988, 'merge', '/mɜːrdʒ/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or join together"]}', NULL, 'merge with / merge into / merge companies', '[{"en":"The two companies merged to form a larger corporation.","zh-TW":"兩家公司合併成為一家更大的企業。"},{"en":"The lanes merge ahead.","zh-TW":"前方車道合併。"}]', '{"noun":"merger","verb":"merge"}', NULL, 2, 1988, NULL),
(1989, 'merger', '/ˈmɜːrdʒər/', 'noun', '{"zh-TW":["合併；併購"],"en":["the combination of two or more companies into one"]}', NULL, 'merger and acquisition / a merger between', '[{"en":"The merger created the largest bank in the country.","zh-TW":"這次合併創造了全國最大的銀行。"},{"en":"Both boards approved the merger last Friday.","zh-TW":"雙方董事會上週五批准了合併案。"}]', '{"verb":"merge","adjective":"merged"}', NULL, 2, 1989, NULL),
(1990, 'merit', '/ˈmerɪt/', 'noun, verb', '{"zh-TW":["優點；功績","值得"],"en":["a good quality or feature","to deserve or be worthy of"]}', NULL, 'on merit / merit attention/consideration', '[{"en":"Each proposal will be judged on its own merit.","zh-TW":"每個提案將根據其本身的優點進行評判。"},{"en":"The idea merits further investigation.","zh-TW":"這個想法值得進一步研究。"}]', '{"noun":"merit","verb":"merit","adjective":"meritorious"}', NULL, 2, 1990, NULL),
(1991, 'message', 'ˈmɛsɪdʒ', 'noun', '{"zh-TW":["訊息；留言","要旨"],"en":["a spoken or written communication","the main point of something"]}', NULL, 'leave a message/key message', '[{"en":"I left a message with the receptionist.","zh-TW":"我留了一條留言給接待員。"}]', '{"verb":"message","adjective":"messaging"}', NULL, 3, 1991, NULL),
(1992, 'method', '/ˈmeθəd/', 'noun', '{"zh-TW":["方法；辦法"],"en":["a way of doing something systematically"]}', NULL, 'teaching/payment method / method of', '[{"en":"We need to find a more efficient method.","zh-TW":"我們需要找到一種更有效率的方法。"},{"en":"What payment methods do you accept?","zh-TW":"你們接受哪些付款方式？"}]', '{"noun":"method, methodology","adjective":"methodical","adverb":"methodically"}', NULL, 2, 1992, NULL),
(1993, 'methodology', '/ˌmɛθəˈdɒlədʒi/', 'noun', '{"zh-TW":["方法論"],"en":["a system of methods used in a particular area"]}', NULL, 'research methodology / agile methodology', '[{"en":"We follow agile methodology in development.","zh-TW":"我們在開發中遵循敏捷方法論。"},{"en":"The research methodology is clearly defined.","zh-TW":"研究方法論有明確的定義。"},{"en":"The company adopted an agile methodology for software development.","zh-TW":"公司採用了敏捷方法論進行軟體開發。"},{"en":"Please describe the methodology used in your study.","zh-TW":"請描述你研究中使用的方法論。"}]', '{"noun":"methodology","adjective":"methodological","adverb":"methodologically"}', NULL, 4, 1993, NULL),
(1994, 'meticulous', '/mɪˈtɪkjələs/', 'adjective', '{"zh-TW":["一絲不苟的；極其仔細的"],"en":["showing great attention to detail"]}', NULL, 'meticulous attention to detail / meticulous planning', '[{"en":"She is meticulous in her work and rarely makes errors.","zh-TW":"她工作一絲不苟，很少犯錯。"},{"en":"Meticulous planning ensured the event''s success.","zh-TW":"細緻的規劃確保了活動的成功。"}]', '{"adjective":"meticulous","adverb":"meticulously"}', NULL, 4, 1994, NULL),
(1995, 'metrics', 'ˈmɛtrɪks', 'noun', '{"zh-TW":["指標；度量","衡量標準"],"en":["measures used to evaluate performance","data points"]}', NULL, 'key metrics/track metrics', '[{"en":"Monitor these key performance metrics.","zh-TW":"監控這些關鍵績效指標。"}]', '{"adjective":"metric"}', NULL, 3, 1995, NULL),
(1996, 'microeconomics', '/ˌmaɪkroʊˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["微觀經濟學"],"en":["the study of individual economic behaviors and decisions"]}', NULL, 'apply microeconomics / microeconomics principles', '[{"en":"Microeconomics helps predict how consumers respond to price changes.","zh-TW":"微觀經濟學有助於預測消費者如何應對價格變化。"},{"en":"Understanding microeconomics is valuable for pricing and market analysis.","zh-TW":"了解微觀經濟學對定價和市場分析很有價值。"}]', NULL, NULL, 5, 1996, NULL),
(1997, 'micromanage', '/ˈmaɪkroʊˌmænɪdʒ/', 'verb', '{"zh-TW":["過度管理；微觀管理"],"en":["to control every small detail of a task or person''s work"]}', NULL, 'avoid micromanaging / tendency to micromanage', '[{"en":"Micromanaging reduces employee autonomy and creativity.","zh-TW":"過度管理降低了員工的自主性和創造力。"},{"en":"Trust your team and avoid the urge to micromanage.","zh-TW":"信任你的團隊，避免過度管理的衝動。"}]', '{"noun":"micromanager","adjective":"micromanaged"}', NULL, 4, 1997, NULL),
(1998, 'middle', '/ˈmɪdəl/', 'noun', '{"zh-TW":["中間；中部"],"en":["the central point or position"]}', NULL, 'middle management / in the middle of', '[{"en":"She is in middle management.","zh-TW":"她是中層管理人員。"},{"en":"We are in the middle of negotiations.","zh-TW":"我們正在談判中。"}]', '{"noun":"middle","adjective":"middle"}', NULL, 2, 1998, NULL),
(1999, 'midterm', '/ˈmɪdtɜːrm/', 'noun', '{"zh-TW":["期中考"],"en":["an exam in the middle of a term"]}', NULL, 'midterm exam / midterm grades', '[{"en":"I''m studying for my midterms.","zh-TW":"我正在準備期中考。"},{"en":"Midterm grades will be posted Friday.","zh-TW":"期中成績將在週五公布。"}]', NULL, NULL, 3, 1999, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2000, 'migrate', '/ˈmaɪɡreɪt/', 'verb', '{"zh-TW":["遷移；移民"],"en":["to move from one place to another"]}', NULL, 'migrate to / migrate data/systems', '[{"en":"Many companies are migrating their data to the cloud.","zh-TW":"許多公司正在將數據遷移到雲端。"},{"en":"Birds migrate south for the winter.","zh-TW":"鳥類冬天遷徙到南方。"}]', '{"noun":"migration, migrant","verb":"migrate","adjective":"migratory"}', NULL, 3, 2000, NULL),
(2001, 'migration', '/maɪˈɡreɪʃən/', 'noun', '{"zh-TW":["數據遷移；系統遷移"],"en":["the process of moving data or systems from one platform to another"]}', NULL, 'data migration / system migration / cloud migration / migration plan', '[{"en":"The cloud migration reduced infrastructure costs by 40%.","zh-TW":"雲端遷移將基礎設施成本降低了40%。"},{"en":"A data migration plan was developed to ensure zero data loss.","zh-TW":"制定了數據遷移計劃以確保零數據遺失。"}]', '{"verb":"migrate","adjective":"migrated"}', NULL, 3, 2001, NULL),
(2002, 'milestone', '/ˈmaɪlstoʊn/', 'noun', '{"zh-TW":["里程碑；重要事件"],"en":["an important event in the development of something"]}', NULL, 'reach/achieve a milestone / project milestone', '[{"en":"Reaching 1 million users was a major milestone.","zh-TW":"達到100萬用戶是一個重要的里程碑。"},{"en":"The project has several key milestones to meet.","zh-TW":"該項目有幾個關鍵里程碑需要完成。"}]', '{"noun":"milestone"}', NULL, 3, 2002, 890),
(2003, 'milk', '/mɪlk/', 'noun', '{"zh-TW":["牛奶"],"en":["a white liquid from cows"]}', NULL, 'milk products / don''t cry over spilled milk', '[{"en":"The cafeteria offers various milk products.","zh-TW":"自助餐廳提供各種乳製品。"},{"en":"Don''t cry over spilled milk; move forward.","zh-TW":"不要為打翻的牛奶哭泣；向前看。"}]', '{"noun":"milk","adjective":"milky","verb":"milk"}', NULL, 1, 2003, NULL),
(2004, 'million', 'ˈmɪljən', 'noun', '{"zh-TW":["百萬","大量"],"en":["a thousand thousand","an extremely large number"]}', NULL, 'one million/million-dollar', '[{"en":"The company earned five million in revenue.","zh-TW":"公司賺了五百萬的收入。"}]', '{"adjective":"million-dollar"}', NULL, 3, 2004, NULL),
(2005, 'mind', '/maɪnd/', 'noun', '{"zh-TW":["【主要意義-名詞】心智；思想；意見","【次要意義-動詞】照料；看管","【次要意義-動詞】介意；在乎","【次要意義-動詞】注意；小心（命令句）"],"en":["[primary - noun] the part of a person that thinks and feels","[secondary - verb] to look after or take care of something","[secondary - verb] to feel bothered or annoyed by something","[secondary - verb] to be careful about something (in imperatives)"]}', NULL, 'mind the gap / bear in mind / never mind / mind your own business / mind the store', '[{"en":"Could you mind the front desk while I attend the meeting?","zh-TW":"我去參加會議時，你能照看前台嗎？"},{"en":"Bear in mind that all expenses must be approved before submission.","zh-TW":"請記住，所有費用必須在提交前獲得批准。"},{"en":"Do you mind if I reschedule our appointment to next Tuesday?","zh-TW":"您介意將我們的預約改到下週二嗎？"}]', '{"adjective":"mindful, mindless","noun":"mindset"}', '動詞 mind = 「照料」（mind the store = 看顧業務），bear in mind（記住），do you mind if（您介意嗎？）均是 TOEIC 高頻職場用語，考生常誤以為 mind 只是名詞「心智」。', 1, 2005, NULL),
(2006, 'mindset', 'ˈmaɪndˌsɛt', 'noun', '{"zh-TW":["心態；思維方式","觀念"],"en":["an established set of attitudes","a way of thinking"]}', NULL, 'growth mindset/positive mindset', '[{"en":"Cultivate a growth mindset.","zh-TW":"培養成長型心態。"}]', NULL, NULL, 3, 2006, NULL),
(2007, 'mineral', '/ˈmɪnərəl/', 'noun, adjective', '{"zh-TW":["礦物；礦產"],"en":["a natural substance found in the earth"]}', NULL, 'mineral resources/deposits/water', '[{"en":"The country is rich in mineral resources.","zh-TW":"該國礦產資源豐富。"},{"en":"Mineral water is available at the front desk.","zh-TW":"前台有提供礦泉水。"}]', '{"noun":"mineral, mining","adjective":"mineral"}', NULL, 3, 2007, NULL),
(2008, 'minibar', '/ˈmɪnibɑːr/', 'noun', '{"zh-TW":["迷你吧；小型冰箱"],"en":["a small refrigerator stocked with drinks in a hotel room"]}', NULL, 'use the minibar / minibar charges', '[{"en":"The minibar is stocked with soft drinks and snacks.","zh-TW":"迷你吧備有軟性飲料和零食。"},{"en":"Minibar charges will appear on your bill.","zh-TW":"迷你吧費用將計入您的帳單。"}]', NULL, NULL, 3, 2008, NULL),
(2009, 'minimize', '/ˈmɪnɪmaɪz/', 'verb', '{"zh-TW":["最小化；減少"],"en":["to reduce to the smallest possible amount"]}', NULL, 'minimize risk/cost/damage', '[{"en":"We must minimize the risk of data loss.","zh-TW":"我們必須將數據丟失的風險降到最低。"},{"en":"The new procedure minimizes waste.","zh-TW":"新程序將浪費減到最少。"}]', '{"noun":"minimum","verb":"minimize","adjective":"minimum, minimal"}', NULL, 3, 2009, 157),
(2010, 'minimum', 'ˈmɪnɪməm', 'noun', '{"zh-TW":["最小值；最低限度","最少量"],"en":["the least possible amount","a lower limit"]}', NULL, 'minimum wage/at a minimum', '[{"en":"The minimum order is 100 units.","zh-TW":"最低訂購量為100件。"}]', '{"adjective":"minimum","adverb":"minimally"}', NULL, 3, 2010, 395),
(2011, 'ministry', '/ˈmɪnɪstri/', 'noun', '{"zh-TW":["部；部門（政府）"],"en":["a government department led by a minister"]}', NULL, 'Ministry of Finance/Education/Health', '[{"en":"The Ministry of Finance released the annual budget.","zh-TW":"財政部發布了年度預算。"},{"en":"She works at the Ministry of Education.","zh-TW":"她在教育部工作。"}]', '{"noun":"ministry, minister","adjective":"ministerial"}', NULL, 3, 2011, NULL),
(2012, 'minor', '/ˈmaɪnər/', 'adjective, noun', '{"zh-TW":["次要的；較小的","未成年人"],"en":["not very important; smaller","a person under the legal age"]}', NULL, 'minor issue/problem/change', '[{"en":"It''s only a minor issue and can be fixed quickly.","zh-TW":"這只是一個小問題，可以很快解決。"},{"en":"There were a few minor adjustments to the schedule.","zh-TW":"行程有一些小的調整。"}]', '{"noun":"minor, minority","adjective":"minor"}', NULL, 2, 2012, NULL),
(2013, 'minute', '/maɪˈnjuːt/', 'adjective', '{"zh-TW":["【主要意義-名詞】分鐘","【次要意義-形容詞】微小的；極細緻的；極詳盡的（重音在第二音節）","【次要意義-複數名詞】會議記錄（minutes）"],"en":["[primary - noun] a unit of time (60 seconds)","[secondary - adjective] extremely small or detailed (stress on second syllable: /maɪˈnjuːt/)","[secondary - plural noun] the official written record of a meeting"]}', NULL, 'minute details / minute examination / take the minutes / approve the minutes', '[{"en":"The inspector carried out a minute examination of the document.","zh-TW":"檢查員對該文件進行了極為詳細的審查。"},{"en":"Could you take the minutes at today''s board meeting?","zh-TW":"你能記錄今天董事會議的會議記錄嗎？"},{"en":"The difference between the two samples was minute but significant.","zh-TW":"兩個樣本之間的差異微乎其微但卻意義重大。"}]', '{"adverb":"minutely","noun":"minuteness"}', 'minute 作形容詞時重音移至第二音節，意為「微小的」；複數 minutes 意為「會議記錄」，兩者都是 TOEIC 高頻陷阱字。', 2, 2013, NULL),
(2014, 'minutes', '/ˈmɪnɪts/', 'noun', '{"zh-TW":["會議記錄"],"en":["an official written record of what was discussed in a meeting"]}', NULL, 'take the minutes / circulate the minutes / approve the minutes', '[{"en":"She was asked to take the minutes during the board meeting.","zh-TW":"她被要求在董事會會議期間記錄會議記錄。"},{"en":"The minutes were approved at the start of the next meeting.","zh-TW":"會議記錄在下次會議開始時獲得批准。"}]', NULL, NULL, 3, 2014, NULL),
(2015, 'misconduct', '/ˌmɪsˈkɑːndʌkt/', 'noun', '{"zh-TW":["不當行為；瀆職"],"en":["unacceptable or improper behavior, especially by a professional"]}', NULL, 'professional/employee misconduct / allegations of misconduct', '[{"en":"He was fired for gross misconduct.","zh-TW":"他因嚴重不當行為被解僱。"},{"en":"The investigation found evidence of financial misconduct.","zh-TW":"調查發現了財務不當行為的證據。"}]', '{"noun":"misconduct"}', NULL, 4, 2015, NULL),
(2016, 'mislead', '/ˌmɪsˈliːd/', 'verb', '{"zh-TW":["誤導；使產生錯誤印象"],"en":["to cause someone to have a wrong impression"]}', NULL, 'mislead consumers/investors / misleading information', '[{"en":"The advertisement was found to mislead consumers.","zh-TW":"該廣告被發現誤導消費者。"},{"en":"Don''t be misled by the low price.","zh-TW":"不要被低價格所誤導。"}]', '{"verb":"mislead","adjective":"misleading"}', NULL, 3, 2016, NULL),
(2017, 'miss', '/mɪs/', 'verb', '{"zh-TW":["錯過；想念"],"en":["to fail to attend or catch","to feel sad about absence"]}', NULL, 'miss the point / miss a deadline', '[{"en":"We cannot miss this opportunity.","zh-TW":"我們不能錯過這個機會。"},{"en":"Don''t miss the deadline.","zh-TW":"別錯過截止日期。"}]', '{"verb":"miss","adjective":"missing","noun":"miss"}', NULL, 1, 2017, NULL),
(2018, 'mission', 'ˈmɪʃən', 'noun', '{"zh-TW":["使命；任務","宗旨"],"en":["a purpose or goal","a duty assigned"]}', NULL, 'company mission/mission statement', '[{"en":"Our mission is to serve customers globally.","zh-TW":"我們的使命是在全球服務客戶。"}]', '{"adjective":"mission-driven"}', NULL, 3, 2018, 158),
(2019, 'mistake', '/mɪˈsteɪk/', 'noun', '{"zh-TW":["錯誤"],"en":["something done incorrectly"]}', NULL, 'make a mistake / by mistake', '[{"en":"Everyone makes mistakes sometimes.","zh-TW":"每個人有時都會犯錯。"},{"en":"I sent the email by mistake.","zh-TW":"我不小心寄了那封郵件。"}]', '{"noun":"mistake","verb":"mistake","adjective":"mistaken"}', NULL, 3, 2019, NULL),
(2020, 'misunderstand', '/ˌmɪsʌndərˈstænd/', 'verb', '{"zh-TW":["誤解；誤會"],"en":["to fail to understand correctly"]}', NULL, 'misunderstand instructions/intentions', '[{"en":"I think you misunderstood my intentions.","zh-TW":"我想你誤解了我的意思。"},{"en":"The email was misunderstood by several recipients.","zh-TW":"這封電子郵件被幾位收件者誤解了。"}]', '{"noun":"misunderstanding","verb":"misunderstand"}', NULL, 5, 2020, NULL),
(2021, 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', '{"zh-TW":["減輕；緩和"],"en":["to make something less severe or harmful"]}', NULL, 'mitigate risk/damage/effects', '[{"en":"Steps were taken to mitigate the environmental impact.","zh-TW":"已採取措施減輕環境影響。"},{"en":"Insurance can help mitigate financial risk.","zh-TW":"保險可以幫助減輕財務風險。"}]', '{"noun":"mitigation","verb":"mitigate","adjective":"mitigating"}', NULL, 3, 2021, 698),
(2022, 'mitigation', '/ˌmɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["緩解；減輕"],"en":["actions taken to reduce the severity of a risk or problem"]}', NULL, 'risk mitigation / mitigation measures / mitigation strategy', '[{"en":"The project team developed mitigation measures for identified risks.","zh-TW":"項目團隊為識別的風險制定了緩解措施。"},{"en":"Mitigation efforts reduced the financial impact of the disruption.","zh-TW":"緩解工作降低了中斷的財務影響。"}]', '{"verb":"mitigate","adjective":"mitigated"}', NULL, 4, 2022, 892),
(2023, 'mix', '/mɪks/', 'verb', '{"zh-TW":["混合"],"en":["to combine different things together"]}', NULL, 'product mix / mix up', '[{"en":"We need a better product mix.","zh-TW":"我們需要更好的產品組合。"},{"en":"There was a mix-up with the orders.","zh-TW":"訂單搞混了。"}]', '{"verb":"mix","noun":"mix","noun2":"mixture","noun3":"mix-up"}', NULL, 1, 2023, NULL),
(2024, 'mobile', '/ˈmoʊbl/', 'adjective, noun', '{"zh-TW":["移動的；手機的","行動電話"],"en":["able to move easily; relating to cell phones","a cell phone"]}', NULL, 'mobile device/app/phone / mobile banking', '[{"en":"Mobile banking has become increasingly popular.","zh-TW":"行動銀行越來越受歡迎。"},{"en":"More users access the site via mobile devices.","zh-TW":"越來越多用戶通過行動裝置訪問網站。"}]', '{"noun":"mobile, mobility","adjective":"mobile","verb":"mobilize"}', NULL, 2, 2024, NULL),
(2025, 'mobility', '/moʊˈbɪləti/', 'noun', '{"zh-TW":["流動性；移動性"],"en":["the ability to move freely; social advancement"]}', NULL, 'social/career mobility / labor mobility', '[{"en":"Career mobility is important to today''s workforce.","zh-TW":"職業流動性對當今勞動力很重要。"},{"en":"The new policy promotes upward social mobility.","zh-TW":"新政策促進了社會向上流動。"}]', '{"noun":"mobility, mobile","adjective":"mobile","verb":"mobilize"}', NULL, 3, 2025, NULL),
(2026, 'mobilize', '/ˈmoʊbɪlaɪz/', 'verb', '{"zh-TW":["動員；調動"],"en":["to organize resources or people for a specific purpose or action"]}', NULL, 'mobilize resources / mobilize a team', '[{"en":"The project manager mobilized the team quickly after contract signing.","zh-TW":"合約簽署後，項目經理迅速動員了團隊。"},{"en":"The government mobilized emergency funds to address the crisis.","zh-TW":"政府調動了緊急資金應對危機。"}]', '{"noun":"mobilization","adjective":"mobilized"}', NULL, 3, 2026, 699),
